254.                             "MINIMUM_VALUE AS MIN_VALUE, " +
255.                             "MAXIMUM_VALUE AS MAX_VALUE, " +
256.                             "INCREMENT AS INCREMENT_BY, " +
257.                             "CYCLE_OPTION AS WILL_CYCLE " +
258.                             "FROM %s ", seqName, seqName));
259.                 }
260.             } catch (DatabaseException e) {
261.                 throw new UnexpectedLiquibaseException("Could not get list of schemas ", e);
262.             }
263.             return j.toString();
264.         } else if (database instanceof SybaseASADatabase) {
265.         	return "SELECT SEQUENCE_NAME, " +
266.                     "START_WITH AS START_VALUE, " +
267.                     "MIN_VALUE, " +
268.                     "MAX_VALUE, " +
269.                     "INCREMENT_BY, " +
270.                     "CYCLE AS WILL_CYCLE " +
271.                     "FROM SYS.SYSSEQUENCE s " +
272.                     "JOIN SYS.SYSUSER u ON s.OWNER = u.USER_ID "+
273.                     "WHERE u.USER_NAME = '" + schema.getName() + "'";
274.         	} else {
275.             throw new UnexpectedLiquibaseException("Don't know how to query for sequences on " + database);
276.         }
277. 
278.     }
279. }
