1. package liquibase.snapshot.jvm;
2. 
3. import liquibase.Scope;
4. import liquibase.database.Database;
5. import liquibase.database.core.*;
6. import liquibase.exception.DatabaseException;
7. import liquibase.exception.UnexpectedLiquibaseException;
8. import liquibase.executor.ExecutorService;
9. import liquibase.snapshot.CachedRow;
10. import liquibase.snapshot.DatabaseSnapshot;
11. import liquibase.snapshot.JdbcDatabaseSnapshot;
12. import liquibase.statement.core.RawSqlStatement;
13. import liquibase.structure.DatabaseObject;
14. import liquibase.structure.core.Catalog;
15. import liquibase.structure.core.Column;
16. import liquibase.structure.core.Index;
17. import liquibase.structure.core.Relation;
18. import liquibase.structure.core.Schema;
19. import liquibase.structure.core.Table;
20. import liquibase.structure.core.UniqueConstraint;
21. import liquibase.util.StringUtil;
22. 
23. import java.sql.SQLException;
24. import java.util.ArrayList;
25. import java.util.HashMap;
26. import java.util.HashSet;
27. import java.util.List;
28. import java.util.Map;
29. import java.util.Set;
30. 
31. public class UniqueConstraintSnapshotGenerator extends JdbcSnapshotGenerator {
32. 
33.     public UniqueConstraintSnapshotGenerator() {
34.         super(UniqueConstraint.class, new Class[]{Table.class});
35.     }
36. 
37.     @Override
38.     public int getPriority(Class<? extends DatabaseObject> objectType, Database database) {
39.         if (database instanceof SQLiteDatabase) {
40.             return PRIORITY_NONE;
41.         }
42.         return super.getPriority(objectType, database);
43.     }
44. 
45.     @Override
46.     protected DatabaseObject snapshotObject(DatabaseObject example, DatabaseSnapshot snapshot) throws DatabaseException {
47.         Database database = snapshot.getDatabase();
48.         UniqueConstraint exampleConstraint = (UniqueConstraint) example;
49.         Relation table = exampleConstraint.getRelation();
50. 
51.         List<Map<String, ?>> metadata = listColumns(exampleConstraint, database, snapshot);
52. 
53.         if (metadata.isEmpty()) {
54.             return null;
55.         }
56.         UniqueConstraint constraint = new UniqueConstraint();
57.         constraint.setRelation(table);
58.         constraint.setName(example.getName());
59.         constraint.setBackingIndex(exampleConstraint.getBackingIndex());
60.         constraint.setInitiallyDeferred(((UniqueConstraint) example).isInitiallyDeferred());
61.         constraint.setDeferrable(((UniqueConstraint) example).isDeferrable());
62.         constraint.setClustered(((UniqueConstraint) example).isClustered());
63. 
64.         for (Map<String, ?> col : metadata) {
65.             String ascOrDesc = (String) col.get("ASC_OR_DESC");
66.             Boolean descending = "D".equals(ascOrDesc) ? Boolean.TRUE : ("A".equals(ascOrDesc) ? Boolean.FALSE : null);
67.             if (database instanceof H2Database) {
68.                 for (String columnName : StringUtil.splitAndTrim((String) col.get("COLUMN_NAME"), ",")) {
69.                     constraint.getColumns().add(new Column(columnName).setDescending(descending).setRelation(table));
70.                 }
71.             } else {
72.                 constraint.getColumns().add(new Column((String) col.get("COLUMN_NAME")).setDescending(descending).setRelation(table));
73.             }
74.             setValidateOptionIfAvailable(database, constraint, col);
75.         }
76. 
77.         return constraint;
78.     }
79. 
80.     /**
81.      * Method to map 'validate' option for UC. This thing works only for ORACLE
82.      *
83.      * @param database         - DB where UC will be created
84.      * @param uniqueConstraint - UC object to persist validate option
85.      * @param columnsMetadata  - it's a cache-map to get metadata about UC
86.      */
87.     private void setValidateOptionIfAvailable(Database database, UniqueConstraint uniqueConstraint, Map<String, ?> columnsMetadata) {
88.         if (!(database instanceof OracleDatabase)) {
89.             return;
90.         }
91.         final Object constraintValidate = columnsMetadata.get("CONSTRAINT_VALIDATE");
92.         final String VALIDATE = "VALIDATED";
93.         if (constraintValidate != null && !constraintValidate.toString().trim().isEmpty()) {
94.             uniqueConstraint.setShouldValidate(VALIDATE.equals(cleanNameFromDatabase(constraintValidate.toString().trim(), database)));
95.         }
96.     }
97. 
98.     @Override
99.     protected void addTo(DatabaseObject foundObject, DatabaseSnapshot snapshot) throws DatabaseException {
100. 
101.         if (!snapshot.getSnapshotControl().shouldInclude(UniqueConstraint.class)) {
102.             return;
103.         }
104. 
105.         if (foundObject instanceof Table) {
106.             Table table = (Table) foundObject;
107.             Database database = snapshot.getDatabase();
108.             Schema schema;
109.             schema = table.getSchema();
110. 
111.             List<CachedRow> metadata;
112.             try {
113.                 metadata = listConstraints(table, snapshot, schema);
114.             } catch (SQLException e) {
115.                 throw new DatabaseException(e);
116.             }
117. 
118.             Set<String> seenConstraints = new HashSet<>();
119. 
120.             for (CachedRow constraint : metadata) {
121.                 UniqueConstraint uq = new UniqueConstraint()
122.                         .setName(cleanNameFromDatabase((String) constraint.get("CONSTRAINT_NAME"), database)).setRelation(table);
123.                 if (constraint.containsColumn("INDEX_NAME")) {
