408.     /**
409.      * Return the cache key for the given UniqueConstraint. Must return the same result as {@link #getCacheKey(Map, Database)}.
410.      * Default implementation uses {@link #includeTableNameInCacheKey(Database)} to determine if the table name should be included in the key or not.
411.      */
412.     protected String getCacheKey(UniqueConstraint example, Database database) {
413.         if (includeTableNameInCacheKey(database)) {
414.             return example.getSchema().getName() + "_" + example.getRelation() + "_" + example.getName();
415.         } else {
416.             return example.getSchema().getName() + "_" + example.getName();
417.         }
418.     }
