420.     /**
421.      * Return the cache key for the given query row. Must return the same result as {@link #getCacheKey(UniqueConstraint, Database)}
422.      * Default implementation uses {@link #includeTableNameInCacheKey(Database)} to determine if the table name should be included in the key or not.
423.      */
424.     protected String getCacheKey(Map<String, ?> row, Database database) {
425.         if (includeTableNameInCacheKey(database)) {
426.             return row.get("CONSTRAINT_CONTAINER") + "_" + row.get("TABLE_NAME") + "_" + row.get("CONSTRAINT_NAME");
