434.      */
435.     protected boolean supportsBulkQuery(Database database) {
436.         return !(database instanceof DerbyDatabase)
437.                 && !(database instanceof FirebirdDatabase)
438.                 && !(database instanceof SybaseASADatabase)
439.                 && !(database instanceof Ingres9Database)
440.                 && !(database instanceof InformixDatabase);
