443.     /**
444.      * Gets an SQL query that returns the constraint names and columns for all UNIQUE constraints.
445.      *
446.      * @param database A database object of the InformixDatabase type
447.      * @param schema   Name of the schema to examine (or null for all)
448.      * @param name     Name of the constraint to examine (or null for all)
449.      * @return A lengthy SQL statement that fetches the constraint names and columns
450.      */
451.     private String getUniqueConstraintsSqlInformix(InformixDatabase database, Schema schema, String name) {
452.         StringBuilder sqlBuf = new StringBuilder();
453. 
454.         sqlBuf.append("SELECT * FROM (\n");
455. 
456.         // Yes, I am serious about this. It appears there are neither CTE/WITH clauses nor PIVOT/UNPIVOT operators
457.         // in Informix SQL.
458.         for (int i = 1; i <= 16; i++) {
459.             if (i > 1)
460.                 sqlBuf.append("UNION ALL\n");
461.             sqlBuf.append(
462.                     String.format("  SELECT\n" +
463.                                     "    CONS.owner,\n" +
464.                                     "    CONS.constrname AS constraint_name,\n" +
465.                                     "    COL.colname AS column_name,\n" +
466.                                     "    CONS.constrtype,\n" +
467.                                     "    %d               AS column_index\n" +
468.                                     "  FROM informix.sysconstraints CONS\n" +
469.                                     "    JOIN informix.sysindexes IDX ON CONS.idxname = IDX.idxname\n" +
470.                                     "    JOIN informix.syscolumns COL ON COL.tabid = CONS.tabid AND COL.colno = IDX.part%d\n",
471.                             i, i
472.                     )
473.             );
474.         }
475. 
476.         // Finish the subquery and filter on the U(NIQUE) constraint type
477.         sqlBuf.append(
478.                 "                ) SUBQ\n" +
479.                         "WHERE constrtype='U' \n");
480. 
481.         String catalogName = database.correctObjectName(schema.getCatalogName(), Catalog.class);
482.         String constraintName = database.correctObjectName(name, UniqueConstraint.class);
483. 
484.         // If possible, filter for catalog name and/or constraint name
485.         if (catalogName != null) {
486.             sqlBuf.append("AND owner='").append(catalogName).append("'\n");
487.         }
488.         if (constraintName != null) {
489.             sqlBuf.append("AND constraint_name='").append(constraintName).append("'");
490.         }
491. 
492.         // For correct processing, it is important that we get all columns in order.
493.         sqlBuf.append("ORDER BY owner, constraint_name, column_index");
494. 
495.         // Return the query
496.         return sqlBuf.toString();
497.     }
498. 
499. }
