112.                                 "SELECT " +
113.                                         "c.INDEX_NAME, " +
114.                                         "3 AS TYPE, " +
115.                                         "c.TABLE_OWNER AS TABLE_SCHEM, " +
116.                                         "c.TABLE_NAME, " +
117.                                         "c.COLUMN_NAME, " +
118.                                         "c.COLUMN_POSITION AS ORDINAL_POSITION, " +
119.                                         "e.COLUMN_EXPRESSION AS FILTER_CONDITION, " +
120.                                         "CASE I.UNIQUENESS WHEN 'UNIQUE' THEN 0 ELSE 1 END AS NON_UNIQUE, " +
121.                                         "CASE c.DESCEND WHEN 'Y' THEN 'D' WHEN 'DESC' THEN 'D' WHEN 'N' THEN 'A' WHEN 'ASC' THEN 'A' END AS ASC_OR_DESC, " +
122.                                         "CASE WHEN tablespace_name = (SELECT default_tablespace FROM user_users) " +
123.                                         "THEN NULL ELSE tablespace_name END AS tablespace_name  " +
124.                                         "FROM ALL_IND_COLUMNS c " +
125.                                         "JOIN ALL_INDEXES i ON i.owner=c.index_owner AND i.index_name = c.index_name and i.table_owner = c.table_owner " +
126.                                         "LEFT OUTER JOIN all_ind_expressions e ON e.index_owner=c.index_owner AND e.index_name = c.index_name AND e.column_position = c.column_position   " +
127.                                         "LEFT OUTER JOIN " + (((OracleDatabase) database).canAccessDbaRecycleBin() ? "dba_recyclebin" : "user_recyclebin") + " d ON d.object_name=c.table_name ";
128.                         if (!isBulkFetchMode || getAllCatalogsStringScratchData() == null) {
129.                             sql += "WHERE c.TABLE_OWNER = '" + database.correctObjectName(catalogAndSchema.getCatalogName(), Schema.class) + "' ";
130.                         } else {
131.                             sql += "WHERE c.TABLE_OWNER IN ('" + database.correctObjectName(catalogAndSchema.getCatalogName(), Schema.class) + "', " + getAllCatalogsStringScratchData() + ")";
132.                         }
133.                         sql += "AND i.OWNER = c.TABLE_OWNER " +
134.                                 "AND d.object_name IS NULL ";
135. 
136. 
137.                         if (!isBulkFetchMode && (tableName != null)) {
138.                             sql += " AND c.TABLE_NAME='" + tableName + "'";
139.                         }
140. 
141.                         if (!isBulkFetchMode && (indexName != null)) {
142.                             sql += " AND c.INDEX_NAME='" + indexName + "'";
143.                         }
144. 
145.                         sql += " ORDER BY c.INDEX_NAME, ORDINAL_POSITION";
146. 
147.                         returnList.addAll(executeAndExtract(sql, database));
148.                     } else if (database instanceof MSSQLDatabase) {
149.                         String tableCat = "original_db_name()";
150. 
151.                         if (9 <= database.getDatabaseMajorVersion()) {
152.                             tableCat = "db_name()";
153.                         }
154.                         //fetch additional index info
155.                         String sql = "SELECT " +
156.                                 tableCat + " as TABLE_CAT, " +
157.                                 "object_schema_name(i.object_id) as TABLE_SCHEM, " +
158.                                 "object_name(i.object_id) as TABLE_NAME, " +
159.                                 "CASE is_unique WHEN 1 then 0 else 1 end as NON_UNIQUE, " +
160.                                 "object_name(i.object_id) as INDEX_QUALIFIER, " +
161.                                 "i.name as INDEX_NAME, " +
162.                                 "case i.type when 1 then 1 ELSE 3 end as TYPE, " +
163.                                 "key_ordinal as ORDINAL_POSITION, " +
164.                                 "COL_NAME(c.object_id,c.column_id) AS COLUMN_NAME, " +
165.                                 "case is_descending_key when 0 then 'A' else 'D' end as ASC_OR_DESC, " +
166.                                 "null as CARDINALITY, " +
167.                                 "null as PAGES, " +
168.                                 "i.filter_definition as FILTER_CONDITION, " +
169.                                 "o.type AS INTERNAL_OBJECT_TYPE, " +
170.                                 "i.*, " +
171.                                 "c.*, " +
172.                                 "s.* " +
173.                                 "FROM sys.indexes i " +
174.                                 "join sys.index_columns c on i.object_id=c.object_id and i.index_id=c.index_id " +
175.                                 "join sys.stats s on i.object_id=s.object_id and i.name=s.name " +
176.                                 "join sys.objects o on i.object_id=o.object_id " +
177.                                 "WHERE object_schema_name(i.object_id)='" + database.correctObjectName(catalogAndSchema.getSchemaName(), Schema.class) + "'";
178. 
179.                         if (!isBulkFetchMode && (tableName != null)) {
180.                             sql += " AND object_name(i.object_id)='" + database.escapeStringForDatabase(tableName) + "'";
181.                         }
182. 
183.                         if (!isBulkFetchMode && (indexName != null)) {
184.                             sql += " AND i.name='" + database.escapeStringForDatabase(indexName) + "'";
185.                         }
186. 
187.                         sql += "ORDER BY i.object_id, i.index_id, c.key_ordinal";
188. 
189.                         returnList.addAll(executeAndExtract(sql, database));
190. 
191.                     } else if (database instanceof Db2zDatabase) {
192.                         String sql = "SELECT i.CREATOR AS TABLE_SCHEM, " +
193.                                 "i.TBNAME AS TABLE_NAME, " +
194.                                 "i.NAME AS INDEX_NAME, " +
195.                                 "3 AS TYPE, " +
196.                                 "k.COLNAME AS COLUMN_NAME, " +
197.                                 "k.COLSEQ AS ORDINAL_POSITION, " +
198.                                 "CASE UNIQUERULE WHEN 'D' then 1 else 0 end as NON_UNIQUE, " +
199.                                 "k.ORDERING AS ORDER, " +
200.                                 "i.CREATOR AS INDEX_QUALIFIER " +
201.                                 "FROM SYSIBM.SYSKEYS k " +
202.                                 "JOIN SYSIBM.SYSINDEXES i ON k.IXNAME = i.NAME " +
203.                                 "WHERE  i.CREATOR = '" + database.correctObjectName(catalogAndSchema.getSchemaName(), Schema.class) + "'" +
204.                                 "AND  k.IXCREATOR = '" + database.correctObjectName(catalogAndSchema.getSchemaName(), Schema.class) + "'";
205.                         if (!isBulkFetchMode && tableName != null) {
206.                             sql += " AND i.TBNAME='" + database.escapeStringForDatabase(tableName) + "'";
207.                         }
208. 
209.                         if (!isBulkFetchMode && indexName != null) {
210.                             sql += " AND i.NAME='" + database.escapeStringForDatabase(indexName) + "'";
211.                         }
212. 
213.                         sql += "ORDER BY i.NAME, k.COLSEQ";
214. 
215.                         returnList.addAll(executeAndExtract(sql, database));
216.                     } else if (!(database instanceof MariaDBDatabase) && database instanceof MySQLDatabase) {
217. 
218.                         //mysql 8.0.13 introduced support for indexes on `lower(first_name)` which comes back in an "expression" column
219.                         String filterConditionValue = "NULL";
220.                         if (database.getDatabaseMajorVersion() > 8 || (database.getDatabaseMajorVersion() == 8 && ((MySQLDatabase) database).getDatabasePatchVersion() >= 13)) {
221.                             filterConditionValue = "EXPRESSION";
222.                         }
223. 
224.                         StringBuilder sql = new StringBuilder("SELECT TABLE_CATALOG AS TABLE_CAT, TABLE_SCHEMA AS TABLE_SCHEM,");
225.                         sql.append(" TABLE_NAME, NON_UNIQUE, NULL AS INDEX_QUALIFIER, INDEX_NAME,");
226.                         sql.append(DatabaseMetaData.tableIndexOther);
227.                         sql.append(" AS TYPE, SEQ_IN_INDEX AS ORDINAL_POSITION, COLUMN_NAME,");
228.                         sql.append("COLLATION AS ASC_OR_DESC, CARDINALITY, 0 AS PAGES, " + filterConditionValue + " AS FILTER_CONDITION FROM INFORMATION_SCHEMA.STATISTICS WHERE");
229.                         sql.append(" TABLE_SCHEMA = '").append(database.correctObjectName(catalogAndSchema.getCatalogName(), Catalog.class)).append("'");
230. 
231.                         if (!isBulkFetchMode && tableName != null) {
232.                             sql.append(" AND TABLE_NAME = '").append(database.escapeStringForDatabase(tableName)).append("'");
233.                         }
234. 
235.                         if (!isBulkFetchMode && indexName != null) {
236.                             sql.append(" AND INDEX_NAME='").append(database.escapeStringForDatabase(indexName)).append("'");
237.                         }
238. 
239.                         sql.append("ORDER BY NON_UNIQUE, INDEX_NAME, SEQ_IN_INDEX");
240. 
241.                         returnList.addAll(executeAndExtract(sql.toString(), database));
242.                     } else {
243.                         /*
244.                          * If we do not know in which table to look for the index, things get a little bit ugly.
245.                          * First, we get a collection of all tables within the catalogAndSchema, then iterate through
246.                          * them until we (hopefully) find the index we are looking for.
247.                          */
248.                         List<String> tables = new ArrayList<>();
249.                         if (tableName == null) {
250.                             // Build a list of all candidate tables in the catalog/schema that might contain the index
251.                             for (CachedRow row : getTables(((AbstractJdbcDatabase) database).getJdbcCatalogName(catalogAndSchema), ((AbstractJdbcDatabase) database).getJdbcSchemaName(catalogAndSchema), null)) {
252.                                 tables.add(row.getString("TABLE_NAME"));
253.                             }
254.                         } else {
255.                             tables.add(tableName);
256.                         }
257. 
258.                         // Iterate through all the candidate tables and try to find the index.
259.                         for (String tableName : tables) {
260.                             ResultSet rs = databaseMetaData.getIndexInfo(
261.                                     ((AbstractJdbcDatabase) database).getJdbcCatalogName(catalogAndSchema),
262.                                     ((AbstractJdbcDatabase) database).getJdbcSchemaName(catalogAndSchema),
263.                                     tableName,
264.                                     false,
265.                                     true);
266.                             List<CachedRow> rows = extract(rs, (database instanceof InformixDatabase));
267.                             returnList.addAll(rows);
268.                         }
269.                     }
270. 
271.                     return returnList;
272.                 }
