464.                 if (!bulk) {
465.                     if (tableName != null) {
466.                         sql += " AND TABLE_NAME='" + database.escapeStringForDatabase(tableName) + "'";
467.                     }
468.                     if (columnName != null) {
469.                         sql += " AND COLUMN_NAME='" + database.escapeStringForDatabase(columnName) + "'";
470.                     }
471.                 }
472.                 sql += " AND " + ((OracleDatabase) database).getSystemTableWhereClause("TABLE_NAME");
473.                 sql += " ORDER BY OWNER, TABLE_NAME, c.COLUMN_ID";
474. 
475.                 return this.executeAndExtract(sql, database);
476.             }
