493.                 String sql = "select " +
494.                         "db_name(" + (databaseName == null ? "" : "db_id('" + databaseName + "')") + ") AS TABLE_CAT, " +
495.                         "object_schema_name(c.object_id" + dbIdParam + ") AS TABLE_SCHEM, " +
496.                         "object_name(c.object_id" + dbIdParam + ") AS TABLE_NAME, " +
497.                         "c.name AS COLUMN_NAME, " +
498.                         "is_filestream, " +
499.                         "is_rowguidcol, " +
500.                         "CASE WHEN c.is_identity = 'true' THEN 'YES' ELSE 'NO' END as IS_AUTOINCREMENT, " +
501.                         "{REMARKS_COLUMN_PLACEHOLDER}" +
502.                         "t.name AS TYPE_NAME, " +
503.                         "dc.name as COLUMN_DEF_NAME, " +
504.                         "dc.definition as COLUMN_DEF, " +
