506.                         "CASE t.name " +
507.                         "WHEN 'bigint' THEN " + java.sql.Types.BIGINT + " " +
508.                         "WHEN 'binary' THEN " + java.sql.Types.BINARY + " " +
509.                         "WHEN 'bit' THEN " + java.sql.Types.BIT + " " +
510.                         "WHEN 'char' THEN " + java.sql.Types.CHAR + " " +
511.                         "WHEN 'date' THEN " + java.sql.Types.DATE + " " +
512.                         "WHEN 'datetime' THEN " + java.sql.Types.TIMESTAMP + " " +
513.                         "WHEN 'datetime2' THEN " + java.sql.Types.TIMESTAMP + " " +
514.                         "WHEN 'datetimeoffset' THEN -155 " +
515.                         "WHEN 'decimal' THEN " + java.sql.Types.DECIMAL + " " +
516.                         "WHEN 'float' THEN " + java.sql.Types.DOUBLE + " " +
517.                         "WHEN 'image' THEN " + java.sql.Types.LONGVARBINARY + " " +
518.                         "WHEN 'int' THEN " + java.sql.Types.INTEGER + " " +
519.                         "WHEN 'money' THEN " + java.sql.Types.DECIMAL + " " +
520.                         "WHEN 'nchar' THEN " + java.sql.Types.NCHAR + " " +
521.                         "WHEN 'ntext' THEN " + java.sql.Types.LONGNVARCHAR + " " +
522.                         "WHEN 'numeric' THEN " + java.sql.Types.NUMERIC + " " +
523.                         "WHEN 'nvarchar' THEN " + java.sql.Types.NVARCHAR + " " +
524.                         "WHEN 'real' THEN " + Types.REAL + " " +
525.                         "WHEN 'smalldatetime' THEN " + java.sql.Types.TIMESTAMP + " " +
526.                         "WHEN 'smallint' THEN " + java.sql.Types.SMALLINT + " " +
527.                         "WHEN 'smallmoney' THEN " + java.sql.Types.DECIMAL + " " +
528.                         "WHEN 'text' THEN " + java.sql.Types.LONGVARCHAR + " " +
529.                         "WHEN 'time' THEN " + java.sql.Types.TIME + " " +
530.                         "WHEN 'timestamp' THEN " + java.sql.Types.BINARY + " " +
531.                         "WHEN 'tinyint' THEN " + java.sql.Types.TINYINT + " " +
532.                         "WHEN 'udt' THEN " + java.sql.Types.VARBINARY + " " +
533.                         "WHEN 'uniqueidentifier' THEN " + java.sql.Types.CHAR + " " +
534.                         "WHEN 'varbinary' THEN " + java.sql.Types.VARBINARY + " " +
535.                         "WHEN 'varbinary(max)' THEN " + java.sql.Types.VARBINARY + " " +
536.                         "WHEN 'varchar' THEN " + java.sql.Types.VARCHAR + " " +
537.                         "WHEN 'varchar(max)' THEN " + java.sql.Types.VARCHAR + " " +
538.                         "WHEN 'xml' THEN " + java.sql.Types.LONGVARCHAR + " " +
539.                         "WHEN 'LONGNVARCHAR' THEN " + java.sql.Types.SQLXML + " " +
540.                         "ELSE " + Types.OTHER + " END AS data_type, " +
541.                         "CASE WHEN c.is_nullable = 'true' THEN 1 ELSE 0 END AS NULLABLE, " +
542.                         "10 as NUM_PREC_RADIX, " +
543.                         "c.column_id as ORDINAL_POSITION, " +
544.                         "c.scale as DECIMAL_DIGITS, " +
545.                         "c.max_length as COLUMN_SIZE, " +
546.                         "c.precision as DATA_PRECISION, " +
547.                         "c.is_computed as IS_COMPUTED " +
548.                         "FROM " + databasePrefix + "sys.columns c " +
549.                         "inner join " + databasePrefix + "sys.types t on c.user_type_id=t.user_type_id " +
550.                         "{REMARKS_JOIN_PLACEHOLDER}" +
551.                         "left outer join " + databasePrefix + "sys.default_constraints dc on dc.parent_column_id = c.column_id AND dc.parent_object_id=c.object_id AND type_desc='DEFAULT_CONSTRAINT' " +
552.                         "WHERE object_schema_name(c.object_id" + dbIdParam + ")='" + ((AbstractJdbcDatabase) database).getJdbcSchemaName(catalogAndSchema) + "'";
553. 
554. 
555.                 if (!bulk) {
556.                     if (tableName != null) {
557.                         sql += " and object_name(c.object_id" + dbIdParam + ")='" + database.escapeStringForDatabase(tableName) + "'";
558.                     }
559.                     if (columnName != null) {
560.                         sql += " and c.name='" + database.escapeStringForDatabase(columnName) + "'";
561.                     }
562.                 }
563.                 sql += "order by object_schema_name(c.object_id" + dbIdParam + "), object_name(c.object_id" + dbIdParam + "), c.column_id";
564. 
565. 
566.                 // sys.extended_properties is added to Azure on V12: https://feedback.azure.com/forums/217321-sql-database/suggestions/6549815-add-sys-extended-properties-for-meta-data-support
567.                 if ((!((MSSQLDatabase) database).isAzureDb()) // Either NOT AzureDB (=SQL Server 2008 or higher)
568.                         || (database.getDatabaseMajorVersion() >= 12)) { // or at least AzureDB v12
569.                     // SQL Server 2005 or later
570.                     // https://technet.microsoft.com/en-us/library/ms177541.aspx
571.                     sql = sql.replace("{REMARKS_COLUMN_PLACEHOLDER}", "CAST([ep].[value] AS [nvarchar](MAX)) AS [REMARKS], ");
572.                     sql = sql.replace("{REMARKS_JOIN_PLACEHOLDER}", "left outer join " + databasePrefix + "[sys].[extended_properties] AS [ep] ON [ep].[class] = 1 " +
573.                             "AND [ep].[major_id] = c.object_id " +
574.                             "AND [ep].[minor_id] = column_id " +
575.                             "AND [ep].[name] = 'MS_Description' ");
576.                 } else {
577.                     sql = sql.replace("{REMARKS_COLUMN_PLACEHOLDER}", "");
578.                     sql = sql.replace("{REMARKS_JOIN_PLACEHOLDER}", "");
579.                 }
580. 
581.                 List<CachedRow> rows = this.executeAndExtract(sql, database);
582. 
583.                 for (CachedRow row : rows) {
584.                     String typeName = row.getString("TYPE_NAME");
585.                     if ("nvarchar".equals(typeName) || "nchar".equals(typeName)) {
586.                         Integer size = row.getInt("COLUMN_SIZE");
587.                         if (size > 0) {
588.                             row.set("COLUMN_SIZE", size / 2);
589.                         }
590.                     } else if ((row.getInt("DATA_PRECISION") != null) && (row.getInt("DATA_PRECISION") > 0)) {
591.                         row.set("COLUMN_SIZE", row.getInt("DATA_PRECISION"));
592.                     }
593.                 }
594. 
595.                 return rows;
596.             }
