599.             protected List<CachedRow> extract(ResultSet resultSet, boolean informixIndexTrimHint) throws SQLException {
600.                 List<CachedRow> rows = super.extract(resultSet, informixIndexTrimHint);
601.                 if ((database instanceof MSSQLDatabase) && !userDefinedTypes.isEmpty()) { //UDT types in MSSQL don't take parameters
602.                     for (CachedRow row : rows) {
603.                         String dataType = (String) row.get("TYPE_NAME");
604.                         if (userDefinedTypes.contains(dataType.toLowerCase())) {
605.                             row.set("COLUMN_SIZE", null);
606.                             row.set("DECIMAL_DIGITS ", null);
607.                         }
608.                     }
609.                 }
610.                 return rows;
611.             }
