708.             protected String getOracleSql(String jdbcSchemaName) {
709.                 String sql = "SELECT  /*+rule*/" +
710.                         "  NULL AS pktable_cat,  " +
711.                         "  p.owner as pktable_schem,  " +
712.                         "  p.table_name as pktable_name,  " +
713.                         "  pc.column_name as pkcolumn_name,  " +
714.                         "  NULL as fktable_cat,  " +
715.                         "  f.owner as fktable_schem,  " +
716.                         "  f.table_name as fktable_name,  " +
717.                         "  fc.column_name as fkcolumn_name,  " +
718.                         "  fc.position as key_seq,  " +
719.                         "  NULL as update_rule,  " +
720.                         "  decode (f.delete_rule, 'CASCADE', 0, 'SET NULL', 2, 1) as delete_rule,  " +
721.                         "  f.constraint_name as fk_name,  " +
722.                         "  p.constraint_name as pk_name,  " +
723.                         "  decode(f.deferrable, 'DEFERRABLE', 5, 'NOT DEFERRABLE', 7, 'DEFERRED', 6) deferrability,  " +
724.                         "  f.validated as fk_validate " +
725.                         "FROM " +
726.                         "all_cons_columns pc " +
727.                         "INNER JOIN all_constraints p " +
728.                         "ON pc.owner = p.owner " +
729.                         "AND pc.constraint_name = p.constraint_name " +
730.                         "INNER JOIN all_constraints f " +
731.                         "ON pc.owner = f.r_owner " +
732.                         "AND pc.constraint_name = f.r_constraint_name " +
733.                         "INNER JOIN all_cons_columns fc " +
734.                         "ON fc.owner = f.owner " +
735.                         "AND fc.constraint_name = f.constraint_name " +
736.                         "AND fc.position = pc.position ";
737.                 if (getAllCatalogsStringScratchData() == null) {
738.                     sql += "WHERE f.owner = '" + jdbcSchemaName + "' ";
739.                 } else {
740.                     sql += "WHERE f.owner IN ('" + jdbcSchemaName + "', " + getAllCatalogsStringScratchData() + ") ";
741.                 }
742.                 sql += "AND p.constraint_type in ('P', 'U') " +
743.                         "AND f.constraint_type = 'R' " +
744.                         "AND p.table_name NOT LIKE 'BIN$%' " +
745.                         "ORDER BY fktable_schem, fktable_name, key_seq";
746.                 return sql;
747.             }
