749.             protected String getMSSQLSql(String jdbcSchemaName, String tableName) {
750.                 //comes from select object_definition(object_id('sp_fkeys'))
751.                 return "select " +
752.                         "convert(sysname,db_name()) AS PKTABLE_CAT, " +
753.                         "convert(sysname,schema_name(o1.schema_id)) AS PKTABLE_SCHEM, " +
754.                         "convert(sysname,o1.name) AS PKTABLE_NAME, " +
755.                         "convert(sysname,c1.name) AS PKCOLUMN_NAME, " +
756.                         "convert(sysname,db_name()) AS FKTABLE_CAT, " +
757.                         "convert(sysname,schema_name(o2.schema_id)) AS FKTABLE_SCHEM, " +
758.                         "convert(sysname,o2.name) AS FKTABLE_NAME, " +
759.                         "convert(sysname,c2.name) AS FKCOLUMN_NAME, " +
760.                         "isnull(convert(smallint,k.constraint_column_id), convert(smallint,0)) AS KEY_SEQ, " +
761.                         "convert(smallint, case ObjectProperty(f.object_id, 'CnstIsUpdateCascade') when 1 then 0 else 1 end) AS UPDATE_RULE, " +
762.                         "convert(smallint, case ObjectProperty(f.object_id, 'CnstIsDeleteCascade') when 1 then 0 else 1 end) AS DELETE_RULE, " +
763.                         "convert(sysname,object_name(f.object_id)) AS FK_NAME, " +
764.                         "convert(sysname,i.name) AS PK_NAME, " +
765.                         "convert(smallint, 7) AS DEFERRABILITY " +
766.                         "from " +
767.                         "sys.objects o1, " +
768.                         "sys.objects o2, " +
769.                         "sys.columns c1, " +
770.                         "sys.columns c2, " +
771.                         "sys.foreign_keys f inner join " +
772.                         "sys.foreign_key_columns k on (k.constraint_object_id = f.object_id) inner join " +
773.                         "sys.indexes i on (f.referenced_object_id = i.object_id and f.key_index_id = i.index_id) " +
774.                         "where " +
775.                         "o1.object_id = f.referenced_object_id and " +
776.                         "o2.object_id = f.parent_object_id and " +
777.                         "c1.object_id = f.referenced_object_id and " +
778.                         "c2.object_id = f.parent_object_id and " +
779.                         "c1.column_id = k.referenced_column_id and " +
780.                         "c2.column_id = k.parent_column_id and " +
781.                         "((object_schema_name(o1.object_id)='" + jdbcSchemaName + "'" +
782.                         " and convert(sysname,schema_name(o2.schema_id))='" + jdbcSchemaName + "' and " +
783.                         "convert(sysname,o2.name)='" + tableName + "' ) or ( convert(sysname,schema_name" +
784.                         "(o2.schema_id))='" + jdbcSchemaName + "' and convert(sysname,o2.name)='" + tableName +
785.                         "' )) order by 5, 6, 7, 9, 8";
786.             }
