796.             private String getDefaultDB2Sql(String jdbcSchemaName, String tableName) {
797.                 return "SELECT  " +
798.                         "  pk_col.tabschema AS pktable_cat,  " +
799.                         "  pk_col.tabname as pktable_name,  " +
800.                         "  pk_col.colname as pkcolumn_name, " +
801.                         "  fk_col.tabschema as fktable_cat,  " +
802.                         "  fk_col.tabname as fktable_name,  " +
803.                         "  fk_col.colname as fkcolumn_name, " +
804.                         "  fk_col.colseq as key_seq,  " +
805.                         "  decode (ref.updaterule, 'A', 3, 'R', 1, 1) as update_rule,  " +
806.                         "  decode (ref.deleterule, 'A', 3, 'C', 0, 'N', 2, 'R', 1, 1) as delete_rule,  " +
807.                         "  ref.constname as fk_name,  " +
808.                         "  ref.refkeyname as pk_name,  " +
809.                         "  7 as deferrability  " +
810.                         "FROM " +
811.                         "syscat.references ref " +
812.                         "join syscat.keycoluse fk_col on ref.constname=fk_col.constname and ref.tabschema=fk_col.tabschema and ref.tabname=fk_col.tabname " +
813.                         "join syscat.keycoluse pk_col on ref.refkeyname=pk_col.constname and ref.reftabschema=pk_col.tabschema and ref.reftabname=pk_col.tabname " +
814.                         "WHERE ref.tabschema = '" + jdbcSchemaName + "' " +
815.                         "and pk_col.colseq=fk_col.colseq " +
816.                         (tableName != null ? " AND fk_col.tabname='" + tableName + "' " : "") +
817.                         "ORDER BY fk_col.colseq";
818.             }
