1286.                     } else {
1287.                         if (database instanceof Db2zDatabase) {
1288.                             String sql = "SELECT 'NULL' AS TABLE_CAT," +
1289.                                     " SYSTAB.TBCREATOR AS TABLE_SCHEM, " +
1290.                                     "SYSTAB.TBNAME AS TABLE_NAME, " +
1291.                                     "COLUSE.COLNAME AS COLUMN_NAME, " +
1292.                                     "COLUSE.COLSEQ AS KEY_SEQ, " +
1293.                                     "SYSTAB.CONSTNAME AS PK_NAME " +
1294.                                     "FROM SYSIBM.SYSTABCONST SYSTAB " +
1295.                                     "JOIN SYSIBM.SYSKEYCOLUSE COLUSE " +
1296.                                     "ON SYSTAB.TBCREATOR = COLUSE.TBCREATOR " +
1297.                                     "WHERE SYSTAB.TYPE = 'P' " +
1298.                                     "AND SYSTAB.TBNAME='" + table + "' " +
1299.                                     "AND SYSTAB.TBCREATOR='" + schemaName + "' " +
1300.                                     "AND SYSTAB.TBNAME=COLUSE.TBNAME " +
1301.                                     "AND SYSTAB.CONSTNAME=COLUSE.CONSTNAME " +
1302.                                     "ORDER BY COLUSE.COLNAME";
1303.                             try {
1304.                                 return executeAndExtract(sql, database);
1305.                             } catch (DatabaseException e) {
1306.                                 throw new SQLException(e);
1307.                             }
1308.                         } else if (database instanceof OracleDatabase) {
1309.                             warnAboutDbaRecycleBin();
1310. 
1311.                             String sql = "SELECT NULL AS table_cat, c.owner AS table_schem, c.table_name, c.column_name as COLUMN_NAME, c.position AS key_seq, c.constraint_name AS pk_name, k.VALIDATED as VALIDATED " +
1312.                                     "FROM all_cons_columns c, all_constraints k " +
1313.                                     "LEFT JOIN " + (((OracleDatabase) database).canAccessDbaRecycleBin() ? "dba_recyclebin" : "user_recyclebin") + " d ON d.object_name=k.table_name " +
1314.                                     "WHERE k.constraint_type = 'P' " +
1315.                                     "AND d.object_name IS NULL " +
1316.                                     "AND k.table_name = '" + table + "' " +
1317.                                     "AND k.owner = '" + ((AbstractJdbcDatabase) database).getJdbcSchemaName(catalogAndSchema) + "' " +
1318.                                     "AND k.constraint_name = c.constraint_name " +
1319.                                     "AND k.table_name = c.table_name " +
1320.                                     "AND k.owner = c.owner " +
1321.                                     "ORDER BY column_name";
1322.                             try {
1323.                                 return executeAndExtract(sql, database);
1324.                             } catch (DatabaseException e) {
1325.                                 throw new SQLException(e);
1326.                             }
1327.                         } else if (database instanceof CockroachDatabase) {
1328.                             // This is the same as the query generated by PGJDBC's getPrimaryKeys method, except it
1329.                             // also adds an `asc_or_desc` column to the result.
1330.                             String sql = "SELECT " +
1331.                                     "  result.table_cat, " +
1332.                                     "  result.table_schem, " +
1333.                                     "  result.table_name, " +
1334.                                     "  result.column_name, " +
1335.                                     "  result.key_seq, " +
1336.                                     "  result.pk_name, " +
1337.                                     "  CASE result.indoption[result.key_seq - 1] & 1 " +
1338.                                     "    WHEN 1 THEN 'D' " +
1339.                                     "    ELSE 'A' " +
1340.                                     "    END AS asc_or_desc " +
1341.                                     "FROM " +
1342.                                     "  (" +
1343.                                     "    SELECT " +
1344.                                     "      NULL AS table_cat, " +
1345.                                     "      n.nspname AS table_schem, " +
1346.                                     "      ct.relname AS table_name, " +
1347.                                     "      a.attname AS column_name, " +
1348.                                     "      (information_schema._pg_expandarray(i.indkey)).n " +
1349.                                     "        AS key_seq, " +
1350.                                     "      ci.relname AS pk_name, " +
1351.                                     "      information_schema._pg_expandarray(i.indkey) AS keys, " +
1352.                                     "      i.indoption, " +
1353.                                     "      a.attnum AS a_attnum " +
1354.                                     "    FROM " +
1355.                                     "      pg_catalog.pg_class AS ct " +
1356.                                     "      JOIN pg_catalog.pg_attribute AS a ON (ct.oid = a.attrelid) " +
1357.                                     "      JOIN pg_catalog.pg_namespace AS n ON " +
1358.                                     "          (ct.relnamespace = n.oid) " +
1359.                                     "      JOIN pg_catalog.pg_index AS i ON (a.attrelid = i.indrelid) " +
1360.                                     "      JOIN pg_catalog.pg_class AS ci ON (ci.oid = i.indexrelid) " +
1361.                                     "    WHERE " +
1362.                                     "      true " +
1363.                                     "      AND n.nspname = '" + ((AbstractJdbcDatabase) database).getJdbcSchemaName(catalogAndSchema) + "' " +
1364.                                     "      AND ct.relname = '" + table + "' " +
1365.                                     "      AND i.indisprimary" +
1366.                                     "  ) " +
1367.                                     "    AS result " +
1368.                                     "WHERE " +
1369.                                     "  result.a_attnum = (result.keys).x " +
1370.                                     "ORDER BY " +
1371.                                     "  result.table_name, result.pk_name, result.key_seq";
1372. 
1373.                             try {
1374.                                 return executeAndExtract(sql, database);
1375.                             } catch (DatabaseException e) {
1376.                                 throw new SQLException(e);
1377.                             }
1378.                         } else {
