1380.                                     databaseMetaData.getPrimaryKeys(
1381.                                             ((AbstractJdbcDatabase) database).getJdbcCatalogName(catalogAndSchema),
1382.                                             ((AbstractJdbcDatabase) database).getJdbcSchemaName(catalogAndSchema),
1383.                                             table
1384.                                     )
1385.                             );
1386.                         }
