1391.                 private String mssqlSql(CatalogAndSchema catalogAndSchema, String tableName) throws DatabaseException {
1392.                     String sql;
1393.                     sql =
1394.                             "SELECT " +
1395.                                     "DB_NAME() AS [TABLE_CAT], " +
1396.                                     "[s].[name] AS [TABLE_SCHEM], " +
1397.                                     "[t].[name] AS [TABLE_NAME], " +
1398.                                     "[c].[name] AS [COLUMN_NAME], " +
1399.                                     "CASE [ic].[is_descending_key] WHEN 0 THEN N'A' WHEN 1 THEN N'D' END AS [ASC_OR_DESC], " +
1400.                                     "[ic].[key_ordinal] AS [KEY_SEQ], " +
1401.                                     "[kc].[name] AS [PK_NAME] " +
1402.                                     "FROM [sys].[schemas] AS [s] " +
1403.                                     "INNER JOIN [sys].[tables] AS [t] " +
1404.                                     "ON [t].[schema_id] = [s].[schema_id] " +
1405.                                     "INNER JOIN [sys].[key_constraints] AS [kc] " +
1406.                                     "ON [kc].[parent_object_id] = [t].[object_id] " +
1407.                                     "INNER JOIN [sys].[indexes] AS [i] " +
1408.                                     "ON [i].[object_id] = [kc].[parent_object_id] " +
1409.                                     "AND [i].[index_id] = [kc].[unique_index_id] " +
1410.                                     "INNER JOIN [sys].[index_columns] AS [ic] " +
1411.                                     "ON [ic].[object_id] = [i].[object_id] " +
1412.                                     "AND [ic].[index_id] = [i].[index_id] " +
1413.                                     "INNER JOIN [sys].[columns] AS [c] " +
1414.                                     "ON [c].[object_id] = [ic].[object_id] " +
1415.                                     "AND [c].[column_id] = [ic].[column_id] " +
1416.                                     "WHERE [s].[name] = N'" + database.escapeStringForDatabase(catalogAndSchema.getSchemaName()) + "' " + // The schema name was corrected in the customized CatalogAndSchema
1417.                                     (tableName == null ? "" : "AND [t].[name] = N'" + database.escapeStringForDatabase(database.correctObjectName(tableName, Table.class)) + "' ") +
1418.                                     "AND [kc].[type] = 'PK' " +
1419.                                     "AND [ic].[key_ordinal] > 0 " +
1420.                                     "ORDER BY " +
1421.                                     "[ic].[key_ordinal]";
1422.                     return sql;
1423.                 }
