31.     protected void addTo(DatabaseObject foundObject, DatabaseSnapshot snapshot) throws DatabaseException, InvalidExampleException {
32.         if (!snapshot.getSnapshotControl().shouldInclude(Index.class)) {
33.             return;
34.         }
35. 
36.         if (foundObject instanceof Table || foundObject instanceof View) {
37.             if (foundObject instanceof View && !addToViews(snapshot.getDatabase())) {
