53.                 Map<String, Index> foundIndexes = new HashMap<>();
54.                 for (CachedRow row : rs) {
55.                     String indexName = row.getString("INDEX_NAME");
56.                     if (indexName == null) {
57.                         continue;
58.                     }
59. 
