65.                     if (index == null) {
66.                         index = new Index();
67.                         index.setName(indexName);
68.                         index.setRelation(relation);
69. 
70.                         short type = row.getShort("TYPE");
71.                         if (type == DatabaseMetaData.tableIndexClustered) {
72.                             index.setClustered(true);
73.                         } else if (database instanceof MSSQLDatabase) {
74.                             index.setClustered(false);
75.                         }
76. 
77.                         foundIndexes.put(indexName, index);
78.                     }
79. 
80.                     String ascOrDesc;
81.                     if (database instanceof Db2zDatabase) {
82.                         ascOrDesc = row.getString("ORDER");
83.                     } else {
84.                         ascOrDesc = row.getString("ASC_OR_DESC");
85.                     }
86.                     Boolean descending = "D".equals(ascOrDesc) ? Boolean.TRUE : ("A".equals(ascOrDesc) ? Boolean
87.                             .FALSE : null);
