101.                     boolean alreadyAddedSimilar = false;
102.                     for (Index index : relation.getIndexes()) {
103.                         if (DatabaseObjectComparatorFactory.getInstance().isSameObject(index, exampleIndex, null, database)) {
104.                             alreadyAddedSimilar = true;
105.                         }
106.                     }
107.                     if (!alreadyAddedSimilar) {
108.                         relation.getIndexes().add(exampleIndex);
109.                     }
110.                 }
111. 
