                 String indexName = cleanNameFromDatabase(rawIndexName, database);
                 String correctedIndexName = database.correctObjectName(indexName, Index.class);

                 if (indexName == null) {
                     continue;
                 }
                 if ((exampleName != null) && !exampleName.equals(correctedIndexName)) {
                     continue;
                 }
