1. package liquibase.snapshot;
2. 
3. import liquibase.CatalogAndSchema;
4. import liquibase.database.Database;
5. import liquibase.database.core.InformixDatabase;
6. import liquibase.database.jvm.JdbcConnection;
7. import liquibase.exception.DatabaseException;
8. import liquibase.exception.UnexpectedLiquibaseException;
9. import liquibase.executor.jvm.ColumnMapRowMapper;
10. import liquibase.executor.jvm.RowMapperResultSetExtractor;
11. import liquibase.util.JdbcUtil;
12. import liquibase.util.StringUtil;
13. 
14. import java.sql.ResultSet;
15. import java.sql.SQLException;
16. import java.sql.Statement;
17. import java.util.*;
18. 
19. class ResultSetCache {
20.     private Map<String, Integer> timesSingleQueried = new HashMap<>();
21.     private Map<String, Boolean> didBulkQuery = new HashMap<>();
22.     private boolean bulkTracking = true;
23. 
24.     private Map<String, Map<String, List<CachedRow>>> cacheBySchema = new HashMap<>();
25. 
26.     private Map<String, Object> info = new HashMap<>();
27. 
28.     public List<CachedRow> get(ResultSetExtractor resultSetExtractor) throws DatabaseException {
29.         try {
30.             String wantedKey = resultSetExtractor.wantedKeyParameters().createParamsKey(resultSetExtractor.database);
31. 
32.             String schemaKey = resultSetExtractor.wantedKeyParameters().createSchemaKey(resultSetExtractor.database);
33. 
34.             Map<String, List<CachedRow>> cache = cacheBySchema.get(schemaKey);
35.             if (cache == null) {
36.                 cache = new HashMap<>();
37.                 cacheBySchema.put(schemaKey, cache);
38.             }
39. 
40.             if (cache.containsKey(wantedKey)) {
41.                 return cache.get(wantedKey);
42.             }
43. 
44.             if (didBulkQuery.containsKey(schemaKey) && didBulkQuery.get(schemaKey)) {
45.                 return new ArrayList<>();
46.             }
47. 
48.             List<CachedRow> results;
49.             boolean bulkQueried = false;
50.             if (resultSetExtractor.shouldBulkSelect(schemaKey, this)) {
51. 
52.                 //remove any existing single fetches that may be duplicated
53.                 if (resultSetExtractor.bulkContainsSchema(schemaKey)) {
54.                     for (Map cachedValue : cacheBySchema.values()) {
55.                         cachedValue.clear();
56.                     }
57.                 } else {
58.                     cache.clear();
59.                 }
60. 
61.                 results = resultSetExtractor.bulkFetch();
62.                 didBulkQuery.put(schemaKey, bulkTracking);
63.                 bulkQueried = true;
64.             } else {
65.                 // Don't store results in real cache to prevent confusion if later fetching all items.
66.                 cache = new HashMap<>();
67.                 Integer previousCount = timesSingleQueried.get(schemaKey);
68.                 if (previousCount == null) {
69.                     previousCount = 0;
70.                 }
71.                 timesSingleQueried.put(schemaKey, previousCount + 1);
72.                 results = resultSetExtractor.fastFetch();
73.             }
74. 
75.             for (CachedRow row : results) {
76.                 for (String rowKey : resultSetExtractor.rowKeyParameters(row).getKeyPermutations()) {
77.                     if (bulkQueried && resultSetExtractor.bulkContainsSchema(schemaKey)) {
78.                         String rowSchema = CatalogAndSchema.CatalogAndSchemaCase.ORIGINAL_CASE.
79.                                 equals(resultSetExtractor.database.getSchemaAndCatalogCase())?resultSetExtractor.getSchemaKey(row):
80.                                 resultSetExtractor.getSchemaKey(row).toLowerCase();
81.                         cache = cacheBySchema.get(rowSchema);
82.                         if (cache == null) {
83.                             cache = new HashMap<String, List<CachedRow>>();
84.                             cacheBySchema.put(rowSchema, cache);
85.                         }
86.                     }
87.                     if (!cache.containsKey(rowKey)) {
