547.     @Override
548.     public String getAutoIncrementClause(final BigInteger startWith, final BigInteger incrementBy, final String generationType, final Boolean defaultOnNull) {
549.         if (!supportsAutoIncrement()) {
550.             return "";
551.         }
552. 
553.         // generate an SQL:2003 STANDARD compliant auto increment clause by default
554. 
555.         String autoIncrementClause = getAutoIncrementClause(generationType, defaultOnNull);
556. 
557.         boolean generateStartWith = generateAutoIncrementStartWith(startWith);
558.         boolean generateIncrementBy = generateAutoIncrementBy(incrementBy);
559. 
560.         if (generateStartWith || generateIncrementBy) {
561.             autoIncrementClause += getAutoIncrementOpening();
562. 
563.             if (generateStartWith) {
564.                 autoIncrementClause += String.format(getAutoIncrementStartWithClause(), (startWith == null) ? defaultAutoIncrementStartWith : startWith);
565.             }
566. 
567.             if (generateIncrementBy) {
568.                 if (generateStartWith) {
569.                     autoIncrementClause += ", ";
570.                 }
571. 
572.                 autoIncrementClause += String.format(getAutoIncrementByClause(), (incrementBy == null) ? defaultAutoIncrementBy : incrementBy);
573.             }
574. 
575.             autoIncrementClause += getAutoIncrementClosing();
576.         }
577. 
578.         return autoIncrementClause;
579.     }
