745.     @Override
746.     public void dropDatabaseObjects(final CatalogAndSchema schemaToDrop) throws LiquibaseException {
747.         ObjectQuotingStrategy currentStrategy = this.getObjectQuotingStrategy();
748.         this.setObjectQuotingStrategy(ObjectQuotingStrategy.QUOTE_ALL_OBJECTS);
749.         try {
750.             DatabaseSnapshot snapshot;
751.             try {
752.                 final SnapshotControl snapshotControl = new SnapshotControl(this);
753.                 final Set<Class<? extends DatabaseObject>> typesToInclude = snapshotControl.getTypesToInclude();
754. 
755.                 //We do not need to remove indexes and primary/unique keys explicitly. They should be removed
756.                 //as part of tables.
757.                 typesToInclude.remove(Index.class);
758.                 typesToInclude.remove(PrimaryKey.class);
759.                 typesToInclude.remove(UniqueConstraint.class);
760. 
761.                 if (supportsForeignKeyDisable() || getShortName().equals("postgresql")) {
762.                     //We do not remove ForeignKey because they will be disabled and removed as parts of tables.
763.                     // Postgress is treated as if we can disable foreign keys because we can't drop
764.                     // the foreign keys of a partitioned table, as discovered in
765.                     // https://github.com/liquibase/liquibase/issues/1212
766.                     typesToInclude.remove(ForeignKey.class);
767.                 }
768. 
769.                 final long createSnapshotStarted = System.currentTimeMillis();
770.                 snapshot = SnapshotGeneratorFactory.getInstance().createSnapshot(schemaToDrop, this, snapshotControl);
771.                 Scope.getCurrentScope().getLog(getClass()).fine(String.format("Database snapshot generated in %d ms. Snapshot includes: %s", System.currentTimeMillis() - createSnapshotStarted, typesToInclude));
772.             } catch (LiquibaseException e) {
773.                 throw new UnexpectedLiquibaseException(e);
774.             }
775. 
776.             final long changeSetStarted = System.currentTimeMillis();
777.             CompareControl compareControl = new CompareControl(
778.                     new CompareControl.SchemaComparison[] {
779.                             new CompareControl.SchemaComparison(
780.                                     CatalogAndSchema.DEFAULT,
781.                                     schemaToDrop)},
782.                     snapshot.getSnapshotControl().getTypesToInclude());
783.             DiffResult diffResult = DiffGeneratorFactory.getInstance().compare(
784.                     new EmptyDatabaseSnapshot(this),
785.                     snapshot,
786.                     compareControl);
787. 
788.             List<ChangeSet> changeSets = new DiffToChangeLog(diffResult, new DiffOutputControl(true, true, false, null).addIncludedSchema(schemaToDrop)).generateChangeSets();
789.             Scope.getCurrentScope().getLog(getClass()).fine(String.format("ChangeSet to Remove Database Objects generated in %d ms.", System.currentTimeMillis() - changeSetStarted));
790. 
791.             boolean previousAutoCommit = this.getAutoCommitMode();
792.             this.commit(); //clear out currently executed statements
793.             this.setAutoCommit(false); //some DDL doesn't work in autocommit mode
794.             final boolean reEnableFK = supportsForeignKeyDisable() && disableForeignKeyChecks();
795.             try {
796.                 for (ChangeSet changeSet : changeSets) {
797.                     changeSet.setFailOnError(false);
798.                     for (Change change : changeSet.getChanges()) {
799.                         if (change instanceof DropTableChange) {
800.                             ((DropTableChange) change).setCascadeConstraints(true);
801.                         }
802.                         SqlStatement[] sqlStatements = change.generateStatements(this);
803.                         for (SqlStatement statement : sqlStatements) {
804.                             Scope.getCurrentScope().getSingleton(ExecutorService.class).getExecutor("jdbc", this).execute(statement);
805.                         }
806. 
807.                     }
808.                     this.commit();
809.                 }
810.             } finally {
811.                 if (reEnableFK) {
812.                     enableForeignKeyChecks();
813.                 }
814.             }
815. 
816.             ChangeLogHistoryServiceFactory.getInstance().getChangeLogService(this).destroy();
817.             LockServiceFactory.getInstance().getLockService(this).destroy();
818. 
819.             this.setAutoCommit(previousAutoCommit);
820.             Scope.getCurrentScope().getLog(getClass()).info(String.format("Successfully deleted all supported object types in schema %s.", schemaToDrop.toString()));
821.         } finally {
822.             this.setObjectQuotingStrategy(currentStrategy);
823.             this.commit();
824.         }
825.     }
