920.                 schemaName = this.getDefaultSchemaName();
921.             }
922. 
923.             if (!supportsCatalogInObjectName(objectType)) {
924.                 catalogName = null;
925.             }
926.             if ((catalogName == null) && (schemaName == null)) {
927.                 return escapeObjectName(objectName, objectType);
928.             } else if ((catalogName == null) || !this.supportsCatalogInObjectName(objectType)) {
929.                 if (isDefaultSchema(catalogName, schemaName) && !getOutputDefaultSchema()) {
930.                     return escapeObjectName(objectName, objectType);
931.                 } else {
932.                     return escapeObjectName(schemaName, Schema.class) + "." + escapeObjectName(objectName, objectType);
933.                 }
934.             } else {
935.                 if (isDefaultSchema(catalogName, schemaName) && !getOutputDefaultSchema() && !getOutputDefaultCatalog
936.                         ()) {
937.                     return escapeObjectName(objectName, objectType);
938.                 } else if (isDefaultSchema(catalogName, schemaName) && !getOutputDefaultCatalog()) {
939.                     return escapeObjectName(schemaName, Schema.class) + "." + escapeObjectName(objectName, objectType);
940.                 } else {
941.                     return escapeObjectName(catalogName, Catalog.class) + "." + escapeObjectName(schemaName, Schema.class) + "." + escapeObjectName(objectName, objectType);
942.                 }
943.             }
944.         } else if (supportsCatalogs()) {
945.             catalogName = StringUtil.trimToNull(catalogName);
946.             schemaName = StringUtil.trimToNull(schemaName);
947. 
948.             if (catalogName != null) {
949.                 if (getOutputDefaultCatalog()) {
950.                     return escapeObjectName(catalogName, Catalog.class) + "." + escapeObjectName(objectName, objectType);
951.                 } else {
952.                     if (!defaultCatalogSet && isDefaultCatalog(catalogName)) {
953.                         return escapeObjectName(objectName, objectType);
954.                     } else {
955.                         return escapeObjectName(catalogName, Catalog.class) + "." + escapeObjectName(objectName, objectType);
956.                     }
957.                 }
958.             } else {
959. 
960.                 //they actually mean catalog name
961.                 if (schemaName != null) {
962.                     if (getOutputDefaultCatalog()) {
963.                         return escapeObjectName(schemaName, Catalog.class) + "." + escapeObjectName(objectName, objectType);
964.                     } else {
