966.                             return escapeObjectName(objectName, objectType);
967.                         } else {
968.                             return escapeObjectName(schemaName, Catalog.class) + "." + escapeObjectName(objectName, objectType);
969.                         }
970.                     }
971.                 } else {
972.                     catalogName = this.getDefaultCatalogName();
973. 
974.                     if (catalogName == null) {
975.                         return escapeObjectName(objectName, objectType);
976.                     } else {
977.                         if (defaultCatalogSet || (isDefaultCatalog(catalogName) && getOutputDefaultCatalog())) {
978.                             return escapeObjectName(catalogName, Catalog.class) + "." + escapeObjectName(objectName, objectType);
979.                         } else {
980.                             return escapeObjectName(objectName, objectType);
981.                         }
982.                     }
983.                 }
984.             }
985. 
986.         } else {
987.             return escapeObjectName(objectName, objectType);
