1063.     @Override
1064.     public String escapeColumnNameList(final String columnNames) {
1065.         StringBuilder sb = new StringBuilder();
1066.         for (String columnName : StringUtil.splitAndTrim(columnNames, ",")) {
1067.             if (sb.length() > 0) {
1068.                 sb.append(", ");
1069.             }
1070.             boolean descending = false;
1071.             if (columnName.matches("(?i).*\\s+DESC")) {
1072.                 columnName = columnName.replaceFirst("(?i)\\s+DESC$", "");
1073.                 descending = true;
1074.             } else if (columnName.matches("(?i).*\\s+ASC")) {
1075.                 columnName = columnName.replaceFirst("(?i)\\s+ASC$", "");
1076.             }
1077.             sb.append(escapeObjectName(columnName, Column.class));
1078.             if (descending) {
1079.                 sb.append(" DESC");
1080.             }
1081.         }
1082.         return sb.toString();
1083.     }
