             }
         } else if (supportsCatalogs()) {
             catalogName = StringUtil.trimToNull(catalogName);
             schemaName = StringUtil.trimToNull(schemaName);

             if (catalogName != null) {
                 if (getOutputDefaultCatalog()) {
