         if (CatalogAndSchemaCase.UPPER_CASE.equals(schemaAndCatalogCase) ||
                 CatalogAndSchemaCase.LOWER_CASE.equals(schemaAndCatalogCase)) {
             return value1.equalsIgnoreCase(value2);
         }

         return value1.equals(value2);
     }

