225.     /**
226.      * Wipes all Liquibase schemas in the database before testing starts. This includes the DATABASECHANGELOG/LOCK
227.      * tables.
228.      */
229.     protected void wipeDatabase() {
230.         emptySchemas.clear();
231.         try {
232.             // Try to erase the DATABASECHANGELOGLOCK (not: -LOG!) table that might be a leftover from a previously
233.             // crashed or interrupted integration test.
234.             // TODO the cleaner solution would be to have a noCachingHasObject() Method in SnapshotGeneratorFactory
235.             try {
236.                 if (database.getConnection() != null) {
237.                     String sql = "DROP TABLE " + database.getDatabaseChangeLogLockTableName();
238.                     for (SqlListener listener : Scope.getCurrentScope().getListeners(SqlListener.class)) {
239.                         listener.writeSqlWillRun(sql);
240.                     }
241.                     ((JdbcConnection) database.getConnection()).getUnderlyingConnection().createStatement().executeUpdate(
242.                             sql
243.                     );
244.                     database.commit();
245.                 }
246.             } catch (SQLException e) {
247.                 if (database instanceof PostgresDatabase) { // throws "current transaction is aborted" unless we roll back the connection
248.                     database.rollback();
249.                 }
250.             }
251. 
252.             SnapshotGeneratorFactory.resetAll();
253.             LockService lockService = LockServiceFactory.getInstance().getLockService(database);
254.             emptyTestSchema(CatalogAndSchema.DEFAULT.getCatalogName(), CatalogAndSchema.DEFAULT.getSchemaName(),
255.                     database);
256.             SnapshotGeneratorFactory factory = SnapshotGeneratorFactory.getInstance();
257. 
258.             if (database.supportsSchemas()) {
259.                 emptyTestSchema(null, DatabaseTestContext.ALT_SCHEMA, database);
260.             }
261.             if (supportsAltCatalogTests()) {
262.                 if (database.supportsSchemas() && database.supportsCatalogs()) {
263.                     emptyTestSchema(DatabaseTestContext.ALT_CATALOG, DatabaseTestContext.ALT_SCHEMA, database);
264.                 }
265.             }
266. 
267.             /*
268.              * There is a special treatment for identifiers in the case when (a) the RDBMS does NOT support
269.              * schemas AND (b) the RDBMS DOES support catalogs AND (c) someone uses "schemaName=..." in a
270.              * Liquibase ChangeSet. In this case, AbstractJdbcDatabase.escapeObjectName assumes the author
271.              * was intending to write "catalog=..." and transparently rewrites the expression.
272.              * For us, this means that we have to wipe both ALT_SCHEMA and ALT_CATALOG to be sure we
273.              * are doing a thorough cleanup.
274.              */
275.             CatalogAndSchema[] alternativeLocations = new CatalogAndSchema[]{
276.                 new CatalogAndSchema(DatabaseTestContext.ALT_CATALOG, null),
277.                 new CatalogAndSchema(null, DatabaseTestContext.ALT_SCHEMA),
278.                 new CatalogAndSchema("LBCAT2", database.getDefaultSchemaName()),
279.                 new CatalogAndSchema(null, "LBCAT2"),
280.                 new CatalogAndSchema("lbcat2", database.getDefaultSchemaName()),
281.                 new CatalogAndSchema(null, "lbcat2")
282.             };
283.             for (CatalogAndSchema location : alternativeLocations) {
284.                 emptyTestSchema(location.getCatalogName(), location.getSchemaName(), database);
285.             }
286. 
287.             database.commit();
288.             SnapshotGeneratorFactory.resetAll();
289.         } catch (Exception e) {
290.             throw new RuntimeException(e);
291.         }
292.     }
