294.     /**
295.      * Transforms a given combination of catalogName and schemaName into the standardized format for the given
296.      * database. If the database has the
297.      *
298.      * @param catalogName catalog name (or null)
299.      * @param schemaName  schema name (or null)
300.      * @param database    the database where the target might exist
301.      * @throws LiquibaseException if any problem occurs during the process
302.      */
303.     protected void emptyTestSchema(String catalogName, String schemaName, Database database)
304.             throws LiquibaseException {
305.         SnapshotGeneratorFactory factory = SnapshotGeneratorFactory.getInstance();
306. 
307.         CatalogAndSchema target = new CatalogAndSchema(catalogName, schemaName).standardize(database);
308.         Schema schema = new Schema(target.getCatalogName(), target.getSchemaName());
309.         if (factory.has(schema, database)) {
310.             if (!emptySchemas.contains(target.toString())) {
311.                 database.dropDatabaseObjects(target);
312.                 emptySchemas.add(target.toString());
313.             }
314.         }
315. 
316.     }
