497.         try {
498.             Statement statement = null;
499.             try {
500.                 // only drop the DATABASECHANGELOG table if it really exists.
501.                 if (SnapshotGeneratorFactory.getInstance().has(
502.                     new Table()
503.                         .setName(database.getDatabaseChangeLogTableName())
504.                         .setSchema(new Schema(database.getLiquibaseCatalogName(), database.getLiquibaseSchemaName())),
505.                         database))
