515.                         listener.writeSqlWillRun(sql);
516.                     }
517.                     statement.execute(sql);
518.                     database.commit();
519.                 }
520.             } catch (Exception e) {
521.                 Scope.getCurrentScope().getLog(getClass()).warning("Probably expected error dropping databasechangelog table");
