import java.sql.*;

public class TestH2 {
    public static void main(String[] args) throws Exception {
        Class.forName("org.h2.Driver");
        Connection conn = DriverManager.getConnection("jdbc:h2:mem:test;DB_CLOSE_DELAY=-1");
        Statement stmt = conn.createStatement();
        stmt.execute("CREATE TABLE compoundIndexTest (firstname VARCHAR(255), lastname VARCHAR(255))");
        stmt.execute("CREATE INDEX idx_compoundtest ON compoundIndexTest (firstname, lastname)");

        DatabaseMetaData meta = conn.getMetaData();

        System.out.println("--- getTables (null, PUBLIC, %, TABLE) ---");
        ResultSet rs = meta.getTables(null, "PUBLIC", "%", new String[]{"TABLE"});
        while (rs.next()) {
            System.out.println("TABLE_CAT: " + rs.getString("TABLE_CAT") + ", TABLE_SCHEM: " + rs.getString("TABLE_SCHEM") + ", TABLE_NAME: " + rs.getString("TABLE_NAME"));
        }

        System.out.println("--- getTables (TEST, PUBLIC, %, TABLE) ---");
        rs = meta.getTables("TEST", "PUBLIC", "%", new String[]{"TABLE"});
        while (rs.next()) {
            System.out.println("TABLE_CAT: " + rs.getString("TABLE_CAT") + ", TABLE_SCHEM: " + rs.getString("TABLE_SCHEM") + ", TABLE_NAME: " + rs.getString("TABLE_NAME"));
        }

        System.out.println("--- getIndexInfo (null, PUBLIC, compoundIndexTest, false, true) ---");
        rs = meta.getIndexInfo(null, "PUBLIC", "COMPOUNDINDEXTEST", false, true);
        while (rs.next()) {
            System.out.println("TABLE_CAT: " + rs.getString("TABLE_CAT") + ", TABLE_SCHEM: " + rs.getString("TABLE_SCHEM") + ", TABLE_NAME: " + rs.getString("TABLE_NAME") + ", INDEX_NAME: " + rs.getString("INDEX_NAME") + ", COLUMN_NAME: " + rs.getString("COLUMN_NAME"));
        }

        System.out.println("--- getIndexInfo (TEST, PUBLIC, compoundIndexTest, false, true) ---");
        rs = meta.getIndexInfo("TEST", "PUBLIC", "COMPOUNDINDEXTEST", false, true);
        while (rs.next()) {
            System.out.println("TABLE_CAT: " + rs.getString("TABLE_CAT") + ", TABLE_SCHEM: " + rs.getString("TABLE_SCHEM") + ", TABLE_NAME: " + rs.getString("TABLE_NAME") + ", INDEX_NAME: " + rs.getString("INDEX_NAME") + ", COLUMN_NAME: " + rs.getString("COLUMN_NAME"));
        }

        conn.close();
    }
}

