1. package liquibase.snapshot;
2. 
3. import liquibase.CatalogAndSchema;
4. import liquibase.Scope;
5. import liquibase.database.Database;
6. import liquibase.database.DatabaseConnection;
7. import liquibase.database.OfflineConnection;
8. import liquibase.database.core.PostgresDatabase;
9. import liquibase.diff.compare.DatabaseObjectComparatorFactory;
10. import liquibase.exception.DatabaseException;
11. import liquibase.exception.UnexpectedLiquibaseException;
12. import liquibase.executor.ExecutorService;
13. import liquibase.servicelocator.ServiceLocator;
14. import liquibase.statement.core.RawSqlStatement;
15. import liquibase.structure.DatabaseObject;
16. import liquibase.structure.core.Schema;
17. import liquibase.structure.core.Table;
18. 
19. import java.util.*;
20. 
21. public class SnapshotGeneratorFactory {
22. 
23.     private static SnapshotGeneratorFactory instance;
24. 
25.     private List<SnapshotGenerator> generators = new ArrayList<>();
26. 
27.     protected SnapshotGeneratorFactory() {
28.         try {
29.             for (SnapshotGenerator generator : Scope.getCurrentScope().getServiceLocator().findInstances(SnapshotGenerator.class)) {
30.                 register(generator);
31.             }
32. 
33.         } catch (Exception e) {
34.             throw new UnexpectedLiquibaseException(e);
35.         }
36. 
37.     }
38. 
39.     /**
40.      * Return singleton SnapshotGeneratorFactory
41.      */
42.     public static synchronized SnapshotGeneratorFactory getInstance() {
43.         if (instance == null) {
44.             instance = new SnapshotGeneratorFactory();
45.         }
46.         return instance;
47.     }
48. 
49.     public static synchronized void reset() {
50.         instance = new SnapshotGeneratorFactory();
51.     }
52. 
53.     public static synchronized void resetAll() {
54.         instance = null;
55.     }
56. 
57.     public void register(SnapshotGenerator generator) {
58.         generators.add(generator);
59.     }
60. 
61.     public void unregister(SnapshotGenerator generator) {
62.         generators.remove(generator);
63.     }
64. 
65.     public void unregister(Class generatorClass) {
66.         SnapshotGenerator toRemove = null;
67.         for (SnapshotGenerator existingGenerator : generators) {
68.             if (existingGenerator.getClass().equals(generatorClass)) {
69.                 toRemove = existingGenerator;
70.             }
71.         }
72. 
73.         unregister(toRemove);
74.     }
75. 
76.     protected SortedSet<SnapshotGenerator> getGenerators(Class<? extends DatabaseObject> generatorClass, Database database) {
77.         SortedSet<SnapshotGenerator> validGenerators = new TreeSet<>(new SnapshotGeneratorComparator(generatorClass, database));
78. 
79.         /*
80.          * Query all SnapshotGenerators if they consider themselves applicable for the generatorClass (e.g. a Table)
81.          * for a specific Database (e.g. MSSQL, Oracle, Postgres...)
82.          */
83.         for (SnapshotGenerator generator : generators) {
84.             if (generator.getPriority(generatorClass, database) > 0) {
85.                 validGenerators.add(generator);
86.             }
87.         }
88.         return validGenerators;
89.     }
90. 
91.     /**
92.      * Checks if a specific object is present in a database
93.      * @param example The DatabaseObject to check for existence
94.      * @param database The DBMS in which the object might exist
95.      * @return true if object existence can be confirmed, false otherweise
96.      * @throws DatabaseException If a problem occurs in the DBMS-specific code
97.      * @throws InvalidExampleException If the object cannot be checked properly, e.g. if the object name is ambiguous
98.      */
99.     public boolean has(DatabaseObject example, Database database) throws DatabaseException, InvalidExampleException {
100.         // @todo I have seen duplicates in types - maybe convert the List into a Set? Need to understand it more thoroughly.
101.         List<Class<? extends DatabaseObject>> types = new ArrayList<>(getContainerTypes(example.getClass(), database));
102.         types.add(example.getClass());
103. 
104.         /*
105.          * Does the query concern the DATABASECHANGELOG / DATABASECHANGELOGLOCK table? If so, we do a quick & dirty
106.          * SELECT COUNT(*) on that table. If that works, we count that as confirmation of existence.
107.          */
108.         // @todo Actually, there may be extreme cases (distorted table statistics etc.) where a COUNT(*) might not be so cheap. Maybe SELECT a dummy constant is the better way?
109.         if ((example instanceof Table) && (example.getName().equals(database.getDatabaseChangeLogTableName()) ||
110.             example.getName().equals(database.getDatabaseChangeLogLockTableName()))) {
111.             try {
112.                 Scope.getCurrentScope().getSingleton(ExecutorService.class).getExecutor("jdbc", database).queryForInt(
113.                         new RawSqlStatement("SELECT COUNT(*) FROM " +
114.                                 database.escapeObjectName(database.getLiquibaseCatalogName(),
115.                                         database.getLiquibaseSchemaName(), example.getName(), Table.class)));
116.                 return true;
117.             } catch (DatabaseException e) {
118.                 if (database instanceof PostgresDatabase) { // throws "current transaction is aborted" unless we roll back the connection
119.                     database.rollback();
120.                 }
121.                 return false;
122.             }
123.         }
124. 
125.         /*
126.           * If the query is about another object, try to create a snapshot of the of the object (or used the cached
127.           * snapshot. If that works, we count that as confirmation of existence.
128.           */
129. 
130.         SnapshotControl snapshotControl = (new SnapshotControl(database, false, types.toArray(new Class[types.size()])));
131.         snapshotControl.setWarnIfObjectNotFound(false);
132. 
133.         if (createSnapshot(example, database,snapshotControl) != null) {
134.             return true;
135.         }
136.         CatalogAndSchema catalogAndSchema;
137.         if (example.getSchema() == null) {
138.             catalogAndSchema = database.getDefaultSchema();
139.         } else {
140.             catalogAndSchema = example.getSchema().toCatalogAndSchema();
141.         }
142.         DatabaseSnapshot snapshot = createSnapshot(catalogAndSchema, database,
143.             new SnapshotControl(database, false, example.getClass()).setWarnIfObjectNotFound(false)
144.         );
145. 
146.         for (DatabaseObject obj : snapshot.get(example.getClass())) {
147.             if (DatabaseObjectComparatorFactory.getInstance().isSameObject(example, obj, null, database)) {
148.                 return true;
149.             }
150.         }
151.         return false;
152.     }
153. 
154.     public DatabaseSnapshot createSnapshot(CatalogAndSchema example, Database database, SnapshotControl snapshotControl) throws DatabaseException, InvalidExampleException {
155.         return createSnapshot(new CatalogAndSchema[] {example}, database, snapshotControl);
156.     }
157. 
158.     /**
159.      * Creates a database snapshot for a given array of catalog/schema combinations.
160.      *
161.      * @param examples        an array of CatalogAndSchema objects
162.      * @param database        the database to work on
163.      * @param snapshotControl the options/settings for snapshot generation
164.      * @return a database snapshot that includes all objects matching the specification
165.      * @throws DatabaseException       if a problem occurs during snapshotting
166.      * @throws InvalidExampleException if the given catalog/schema combinations are invalid (e.g. duplicates)
167.      */
168.     public DatabaseSnapshot createSnapshot(CatalogAndSchema[] examples, Database database,
