        }
        return new DatabaseDataType(name, parameters);
    }

    Object[] parameters = getParameters();
    if (database instanceof liquibase.database.core.H2Database) {
        try {
            if (database.getDatabaseMajorVersion() >= 2) {
                if (parameters != null && parameters.length > 0) {
                    Object[] newParameters = new Object[parameters.length];
                    for (int i = 0; i < parameters.length; i++) {
                        if (parameters[i] != null) {
                            String paramStr = parameters[i].toString();
                            if (paramStr.matches("\\d+")) {
                                long val = Long.parseLong(paramStr);
                                if (val > 1048576L) {
                                    newParameters[i] = 1048576L;
                                    continue;
                                }
                            }
                        }
                        newParameters[i] = parameters[i];
                    }
                    parameters = newParameters;
                }
            }
        } catch (Exception e) {
            // ignore
        }
    }

    DatabaseDataType type = new DatabaseDataType(name.toUpperCase(Locale.US), parameters);
    type.addAdditionalInformation(additionalInformation);

    return type;
}

